import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`deal-room-builder`,heroTitle:`Build your deal room in minutes`,heroSubtitle:`Perplexity Computer researches the prospect's industry challenges, financial performance, tech stack, and competitive landscape, then generates a complete digital deal room document including a personalized executive summary, ROI model with their actual metrics, relevant case studies, and implementation timeline.`,inputUrlCta:`Build your deal room`,inputUrlPlaceholder:`example.com`,inputUrlPrefill:`Go to {url} and build a practical strategy from this brief. Use this brief as context: Paste a prospect company URL and describe your product. Computer researches the prospect's industry challenges, financial performance, tech stack, and competitive landscape, then generates a complete digital deal room document including a personalized executive summary, ROI model with their actual metrics, relevant case studies, and implementation timeline. (1) Review the current setup and relevant context. (2) Benchmark strong examples or market expectations. (3) Design the workflow, structure, or roadmap that best fits this business. (4) Prioritize the highest-impact changes, experiments, or milestones. (5) Deliver a clean plan with rationale, sequencing, and ready-to-execute next steps.`,heroOverlaySteps:[`Reviewing the URL to understand the current state and constraints`,`Benchmarking strong examples and identifying the biggest gaps`,`Designing a practical structure, roadmap, or execution path`,`Plan with sequencing, priorities, and next steps ready to share`],generatingSteps:[`Reviewing {url} to understand the current situation and priorities`,`Designing an agent to benchmark expectations and organize the work into a strategy`,`Configuring prioritization, sequencing, and execution planning`,`Packaging the work into a practical roadmap with rationale and next steps`],featureSectionTitle:`From scattered context to a practical plan`,featureCardTitles:[`Connects to your revenue workflow`,`Outputs your team can execute`],featureCardDescriptions:[`Computer breaks the work into focused tasks, spins up specialized agents, and matches each task to the model that fits it best.`,`Sheets, CRM tools, Docs, and outbound workflows stay in the loop so the work moves straight into the tools your team already uses.`,`Benchmarks. Priorities. Sequence. Execution notes. Computer gives you a plan that is ready to put into motion.`],capabilitySectionTitle:`Your strategy partner, on demand`,capabilitySectionSubtitle:`Paste your URL, step away, and come back to a practical plan with clear sequencing.`,capabilityCards:[{title:`Current-State Review`,description:`Computer can review the current setup, identify the real constraints, and frame the plan around what is most likely to move outcomes.`},{title:`Benchmarking`,description:`Computer can compare the business against strong examples and market expectations to highlight the biggest gaps worth addressing.`},{title:`Plan Design`,description:`Computer can turn the findings into a practical roadmap, workflow, or structure that the team can execute in sequence.`},{title:`Connect Your Tools`,description:`Computer can package the plan into Docs, Sheets, Notion, Jira, and other planning tools so owners can act on it quickly.`},{title:`Prioritized Sequencing`,description:`Computer can rank the work by leverage and dependencies so the team knows what should happen now versus later.`},{title:`Update the Plan`,description:`Computer can revisit the strategy later, compare what changed, and recommend the next actions based on new information.`}]});export{t as default};
